def lamb_candidate(n):
    values = {'initial_condition': 4/n**2, f'A monotone:x_{n},x_star': 4/n}
    values.update({f'A monotone:x_{k},x_{k+1}': 4*k*(k+1)/n**2 for k in range(1,n)})
    values['A Lipschitz:x_0,x_1'] = 2/n**2
    values.update({f'A Lipschitz:x_{k},x_{2*k-1}/2': 2*k*k/n**2 for k in range(2,n+1)})
    return values

